-- Growth content: restore Luke's wording, which lost every apostrophe when it was seeded.
--
-- The seed stripped all 12 contractions and quotation marks out of Luke's copy
-- ("don't" -> "do not", '"um"' -> 'um'), and trimmed several sentences short.
-- It also left the six "why people buy" principles stored twice -- once in the
-- Course lesson, once on the Philosophy tab -- with the two copies disagreeing.
-- Both now come from the same text Luke wrote.
--
-- Values are dollar-quoted, which is how the apostrophes survive this time.
-- Pricing keeps the Klaviyo Email service and the Stripe links, which are ours
-- and are not in Luke's file.

update growth_settings set value = $json${"lessons": [{"blocks": [{"k": "p", "t": "Be yourself. Be like water: adapt to the conversation instead of forcing a script. Take your time, listen, and let the conversation breathe. The aim is to understand their business, their needs, and what matters to them."}, {"k": "h", "t": "Questions to explore"}, {"items": ["Could you walk me through your website and what you offer?", "Who are your main customers?", "How is your team set up?", "What are you doing for marketing at the moment?", "What's working, and what would you like to improve?", "What made you look for help now?", "What would a successful outcome look like for you?"], "k": "ul"}, {"k": "p", "t": "Follow interesting answers with: \"Tell me more about that.\""}], "do": "Ask one question at a time. After every answer say: Tell me more about that.", "g": "Be like water. Listen first and let them talk.", "go": [], "id": "open", "min": 6, "t": "Open relaxed and curious"}, {"blocks": [{"h": "They want to trust you, but their ancient survival brain is on high alert", "k": "b", "t": "Be calm, confident and honest. Don't oversell. Trust is earned by how you show up, not what you say."}, {"h": "They want to feel heard and understood", "k": "b", "t": "Ask thoughtful questions and really listen. Show them you get where they're coming from and what they need. Echo their words. Validate their concerns. Make them feel seen and respected."}, {"h": "They want someone who can lead", "k": "b", "t": "Guide the conversation with clarity and confidence. Have a plan, and help them feel they're in good hands."}, {"h": "They want someone real", "k": "b", "t": "Don't try too hard. Be human. People buy from people, not perfect pitches."}, {"h": "They want to say yes. They're just quietly checking that everything feels right.", "k": "b", "t": "So remove doubt by being transparent, helpful and easy to talk with. Confidence is built through calm clarity, real connection and leading with honesty."}, {"h": "They want to know we are a smart and thoughtful company", "k": "b", "t": "Share quick, relevant examples. Speak with authority and answer their questions."}], "do": "On your next call, learn what they want before you say a word about what you sell.", "g": "This is the key to selling.", "go": [["See the principles", "phil"]], "id": "why", "min": 5, "t": "Understand why people buy"}, {"blocks": [{"k": "p", "t": "Know these well enough to say them without sounding rehearsed."}, {"items": ["What does ReachGiant do?", "What services do you offer?", "Why should I choose you?", "How do you communicate?", "How much does it cost?", "How long does it take?", "How do I move forward?", "Is there a long contract?", "Can you guarantee results?", "Who will actually work on my account?"], "k": "ul"}], "do": "Say How do I move forward? out loud, three times.", "g": "Short, natural answers to the questions everyone asks.", "go": [["Open Clear answers", "clear"]], "id": "clear", "min": 8, "t": "Have clear answers ready"}, {"blocks": [{"k": "h", "t": "Delivery"}, {"items": ["Replace \"um\" with a short pause.", "Ask one question at a time.", "Let the prospect finish before responding.", "Stay flexible rather than following a rigid sequence.", "Summarise what you heard: \"So your main priority is ___, and the biggest obstacle is ___. Have I understood that correctly?\""], "k": "ul"}, {"k": "h", "t": "Words that help"}, {"items": ["Elucidate: make something clear. \"Let me elucidate how that would work.\"", "Minutiae: small details. \"Before we get into the minutiae, let's agree on the main goal.\"", "Synthesize: combine information into a clear understanding. \"Let me synthesize what you've shared.\"", "Synthesis: the resulting combined understanding. \"Here's my synthesis of what you need.\""], "k": "ul"}, {"k": "p", "t": "Use a few useful words when they fit. Clarity comes first. Use familiar language whenever it feels more natural."}], "do": "On your next call, swap every um for a short pause.", "g": "Sound calm, clear and confident.", "go": [], "id": "voice", "min": 5, "t": "Delivery and vocabulary"}, {"blocks": [{"k": "p", "t": "Learn the packages and what each one includes, then the same plain line every time."}, {"items": ["Three month minimum, billed one month at a time", "10 day exit, and the client owns every account", "Ad spend is on top and paid straight to Google or Meta", "Never promise results. Promise daily work and honesty."], "k": "ul"}], "do": "Say the price, what is included, and the exit in one breath.", "g": "Prices, the three month minimum and the 10 day exit.", "go": [["Open Pricing", "pricing"]], "id": "offer", "min": 5, "t": "Know the offer"}, {"blocks": [{"h": "1. Open", "k": "b", "t": "Warm hello. Say how long you have. Ask what made them book."}, {"h": "2. Listen", "k": "b", "t": "Ask about the business, what they run now, and what has gone wrong. Let them talk. Repeat their words back."}, {"h": "3. Find the worry", "k": "b", "t": "Budget, long contracts, past agencies, downtime. Name it out loud so it feels safe."}, {"h": "4. Offer", "k": "b", "t": "Say the plan in plain words: what we do, what it costs, the 3 month minimum and 10 day exit."}, {"h": "5. Email in 10 minutes", "k": "b", "t": "Send the recap and offer while the call is fresh. Ask for a clear yes."}], "do": "Send the recap and offer within ten minutes of the call.", "g": "Name the worry, answer it, then make the next step small.", "go": [["See the questions", "qa"], ["Call script", "script"]], "id": "close", "min": 8, "t": "Handle worries and ask for the yes"}, {"blocks": [{"k": "p", "t": "Just understand what you did right and wrong."}, {"items": ["What questions did the prospect ask?", "Which questions come up repeatedly?", "Where did I hesitate or give an unclear answer?", "Did I explore their answer or move on too quickly?", "Did I understand their main need before offering a solution?", "Was the next step clear?"], "k": "ul"}], "do": "After your next call, answer two questions: what went right, and what went wrong?", "g": "Turn each call into a lesson.", "go": [], "id": "review", "min": 5, "t": "Review every call"}]}$json$::jsonb where key = 'course';

update growth_settings set value = $json${"checklist": ["Stay calm, honest, and don't oversell", "Listen and ask thoughtful questions", "Be real, not scripted or salesy", "Make things easy to trust and say yes", "Give smart insights, just a little..."], "tips": [{"h": "They want to trust you, but their ancient survival brain is on high alert", "t": "Be calm, confident and honest. Don't oversell. Trust is earned by how you show up, not what you say."}, {"h": "They want to feel heard and understood", "t": "Ask thoughtful questions and really listen. Show them you get where they're coming from and what they need. Echo their words. Validate their concerns. Make them feel seen and respected."}, {"h": "They want someone who can lead", "t": "Guide the conversation with clarity and confidence. Have a plan, and help them feel they're in good hands."}, {"h": "They want someone real", "t": "Don't try too hard. Be human. People buy from people, not perfect pitches."}, {"h": "They want to say yes. They're just quietly checking that everything feels right.", "t": "So remove doubt by being transparent, helpful and easy to talk with. Confidence is built through calm clarity, real connection and leading with honesty."}, {"h": "They want to know we are a smart and thoughtful company", "t": "Share quick, relevant examples. Speak with authority and answer their questions."}]}$json$::jsonb where key = 'philosophy';

update growth_settings set value = $json${"flow": [{"h": "Open", "t": "Warm hello. Say how long you have. Ask what made them book."}, {"h": "Listen", "t": "Ask about the business, what they run now, and what has gone wrong. Let them talk. Repeat their words back."}, {"h": "Find the worry", "t": "Budget, long contracts, past agencies, downtime. Name it out loud so it feels safe."}, {"h": "Offer", "t": "Say the plan in plain words: what we do, what it costs, the 3 month minimum and 10 day exit."}, {"h": "Email in 10 minutes", "t": "Send the recap and offer while the call is fresh. Ask for a clear yes."}], "worries": [{"a": "Start small, fix tracking first, and only grow when it works. Small teams like ours give small accounts real attention.", "q": "Is it worth it at my budget?"}, {"a": "No annual lock in. 3 month minimum and a 10 day exit.", "q": "I don't want a long contract."}, {"a": "Small client roster, daily work, a US team that answers. Show the plan before asking for the yes.", "q": "Past agencies let me down."}, {"a": "We help with verification and policy flags, and we watch the account daily so downtime stays short.", "q": "Google keeps pausing my ads."}]}$json$::jsonb where key = 'script';

update growth_settings set value = $json${"notes": ["Ad spend: packages cover up to $15,000 a month in ad spend. Above that there is a fixed scale fee by spend level, not a percentage.", "Terms we have used on calls: no annual lock in, 3 month minimum, 10 day exit. Ask before quoting below list."], "packs": [{"inc": "Google Ads + Meta Ads", "link": "https://buy.stripe.com/aFacN67Ay9yE7VzarIeIw1P", "name": "Paid Ads Volt", "price": "$3,000", "tag": "Pack 1", "top": false, "txt": "Full management across Search, Instagram and Facebook. Clear benchmarks, controlled spend, steady lead flow."}, {"inc": "Google Ads + SEO", "link": "https://buy.stripe.com/aFa5kEbQOaCI7Vz8jAeIw1Q", "name": "Google Powerhouse", "price": "$3,000", "tag": "Pack 2", "top": true, "txt": "Paid and organic working together. Ads bring results now, SEO builds demand over time."}, {"inc": "All services", "link": "https://buy.stripe.com/aFa28s7Ayh16dfTgQ6eIw1W", "name": "Rocket Fuel", "price": "$5,000", "tag": "Pack 3", "top": false, "txt": "Landing pages plus Google Ads and paid media to scale fast, with more testing and faster learning."}], "services": [{"l": "https://buy.stripe.com/3cI14o8EC9yE6RvarIeIw1S", "n": "Google Ads", "p": "$1,500", "w": "Clicks but not enough real leads. Wants buyers, clear tracking, weekly improvements."}, {"l": "https://buy.stripe.com/9B6dRa8ECcKQ7Vz1VceIw1U", "n": "Meta Ads", "p": "$2,000", "w": "Wants steady leads or sales from Facebook and Instagram. Trust based offers."}, {"l": "https://buy.stripe.com/8x28wQ0866ms1xb43keIw1V", "n": "SEO Management", "p": "$2,500", "w": "Wants inbound leads without paying for every click. Compounds over time."}, {"l": "", "n": "Klaviyo Email", "p": "$3,500", "w": "Wants more from leads they already have."}, {"l": "", "n": "Website Design", "p": "Custom", "w": "Site no longer fits the business, or visitors are unsure what to do next."}]}$json$::jsonb where key = 'pricing';

update growth_settings set value = $json${"areas": [{"goal": "Build trust in the first minute and find out what they want.", "id": "open", "s": [{"b": "Thanks for making the time. Before I say anything, what made you book this, and what would a good outcome look like for you?", "p": "Hi, I have about ten minutes. What is this call about?"}, {"b": "That is a fair question. Tell me a bit about your business first, so I can tell you honestly if we are the right fit.", "p": "So you run an agency. What makes you different from the last ten I talked to?"}, {"b": "Good question. I want this call to be useful for you. What is the one thing you need to leave with today?", "p": "Before we start, what do you actually want from this?"}], "t": "Opening the call", "who": "Dana, owner of a busy home services business. Guarded and short on time."}, {"goal": "Name the worry, answer it calmly, and keep the door open.", "id": "worry", "s": [{"b": "That makes sense to check. Can I ask what that other quote included? Then we can see what is really different, and what fits your budget.", "p": "Your fee is more than another agency quoted me."}, {"b": "Of course, that is a big decision. What would your partner most want to know? I can send you a short summary you can share together.", "p": "I need to think about it and talk to my partner."}, {"b": "I hear you, and you are right to be careful. Your ad accounts stay in your name, you can leave on 10 days notice, and you can read our reviews first. What went wrong last time?", "p": "I got burned by an agency last year. Why would you be different?"}], "t": "Handling worries", "who": "Marcus, who is comparing your price with another quote."}, {"goal": "Explain the offer simply and tie it to what they want.", "id": "offer", "s": [{"b": "We help businesses get more customers online, with Google Ads, Meta ads, SEO, AI search, and branding and web development. For a business like yours I would start with the one that brings buyers fastest. Which matters most to you right now?", "p": "What exactly do you do for a business like mine?"}, {"b": "We are usually set up in about 7 days after you say yes. Results take a little longer, and most businesses know within the first month or two if it is working.", "p": "How long does it take before I see anything?"}, {"b": "It means we need three months to set things up and test properly. You pay one month at a time, and if it is not right, you can leave with 10 days notice.", "p": "What does the three month minimum mean in plain words?"}], "t": "Explaining the offer", "who": "Priya, a small business owner who wants a plain explanation."}, {"goal": "Make the next step small, clear and easy to say yes to.", "id": "yes", "s": [{"b": "Great. Next I send you a payment link and a short onboarding form. We are set up in about 7 days. Shall I send it now?", "p": "Okay, this sounds good. What do I do next?"}, {"b": "Happy to. I will send the plan and next steps today. Can we book 15 minutes this week so I can answer any questions?", "p": "Send me something and I will take a look."}, {"b": "That is fair. What would need to be true for you to feel ready? If it helps, we can start with one channel and build from there.", "p": "I am interested, but I am not ready to pay today."}], "t": "Asking for the yes", "who": "Tom, who is interested but not sure what happens next."}]}$json$::jsonb where key = 'practice';

update growth_settings set value = $json${"tasks": [{"d": 0, "t": "Read the pricing and packages (Pricing tab)"}, {"d": 0, "t": "Listen to 4 Fathom calls (Calls to watch tab)"}, {"d": 0, "t": "Write 3 lines per call: what they wanted, what we asked, why they did or didn't buy"}, {"d": 0, "t": "One hour of Meta basics"}, {"d": 0, "t": "Get set up in Claude and the Call Ledger"}, {"d": 1, "t": "Sit in on 2 or 3 live calls, silent, taking notes"}, {"d": 1, "t": "10 minute debrief after each call"}, {"d": 1, "t": "Run a mock call with Luke as the client"}, {"d": 1, "t": "Record a Loom of your pitch"}, {"d": 1, "t": "Write follow up emails from the Fathom notes"}, {"d": 2, "t": "Take 1 or 2 real calls with Luke listening"}, {"d": 2, "t": "Get one keep and one fix after each call"}, {"d": 2, "t": "Send follow ups, Luke reviews first"}, {"d": 2, "t": "Re-record the Loom pitch and compare"}]}$json$::jsonb where key = 'training_plan';
